# -*- coding: utf-8 -*-
"""Сделка для Pintel Оценка: наши данные → её поля.

Писать в базу Оценки с точки нельзя — порт Postgres закрыт наружу, а своего сервера мы
больше не держим. Сделку создаёт сам бот Оценки: он на сервере, база у него под рукой.
Приложение готовит посылку здесь, отдаёт её боту через Telegram (ocenka_tg.py), а вставку
делает обработчик бота (deploy/оценка_бот/).

Поля — её, и мелочи важны, они разобраны по её исходникам:

* **видео обязательно.** Открытие сделки у неё делает
  `media = [InputMediaVideo(media=device.video_phone)]` без проверки на пусто: сделка без
  видео просто не открывается по кнопке. Видео принимает бот — он же и не даёт создать
  сделку, пока его нет.
* **статус как у бота.** «Не был в ремонте» и есть автоцена → status_id 1 (клиенту сразу
  видна цена), иначе status_id 2 — сделка уходит админу на ручную оценку. Правило живёт
  там, где делается вставка: deploy/оценка_бот/kiosk_core.py.
* **словарь полей — её, и не только для вида.** Проверено по выгрузке базы (14 450 сделок):
  `sim` бывает «Dual sim», «E-sim», «Прочее», «Стандарт»; `phone_status` — «Не был в
  ремонте», «Ранее был в ремонте», «Присутствует дефект», «Прочее». Главное — два поля,
  которые уходят дальше карточки:

  - **`akb` — это диапазон, а не «86%».** Её словарь: 0-74, 75-79, 80-85, 86-90, 91-95,
    96-99, 100, «100 (0-30)», «нет информации». По нему `utils/google_price.py` выбирает
    колонку в прайсе (`AKB_COL_INDEX_BY_STATE`), а `ms_auto_supply` — строку приёмки.
    Чужое значение ломает автооценку, а не просто вид карточки. Точный процент идёт
    отдельно, в `akb_exact`.
  - **`color` — одно английское слово заглавными** (BLACK, NATURAL, DEEP PURPLE…). Оно
    попадает в название товара МойСклада: «БУ IP 14 PRO 256 GB 86% BLACK (K)». Русское
    «чёрный / графитовый» из кода корпуса сделало бы название нечитаемым.
"""
from __future__ import annotations

import logging
import re

log = logging.getLogger("pintel.ocenka")

ВЕРСИЯ_ПОСЫЛКИ = 1
SIM_ВАРИАНТЫ = ("Dual sim", "E-sim", "Прочее", "Стандарт")
СТАТУС_ЧИСТЫЙ = "Не был в ремонте"
СТАТУС_РЕМОНТ = "Ранее был в ремонте"

# Диапазоны АКБ — её кнопки (keyboards.akb_kb) и ключи прайса (google_price).
АКБ_НЕТ = "нет информации"
АКБ_НОВАЯ = "100 (0-30)"              # 100% и почти без циклов — отдельная колонка в прайсе
НОВАЯ_ЦИКЛОВ = 30
АКБ_ДИАПАЗОНЫ = ((96, "96-99"), (91, "91-95"), (86, "86-90"), (80, "80-85"), (75, "75-79"))

# Цвет — её словарь: английское слово заглавными, оно уходит в название товара МойСклада.
# Слева — то, что отдаём мы: названия Apple и русские пары из кода корпуса (ENCLOSURE_COLOURS).
ЦВЕТА_ОЦЕНКИ = {
    "чёрный": "BLACK", "черный": "BLACK", "графитовый": "GRAPHITE", "белый": "WHITE",
    "серебристый": "SILVER", "золотой": "GOLD", "розовый": "PINK", "розовое золото": "PINK",
    "натуральный титан": "NATURAL", "jet black": "BLACK", "красный": "RED", "жёлтый": "YELLOW",
    "желтый": "YELLOW", "оранжевый": "ORANGE", "коралловый": "CORAL", "синий": "BLUE",
    "фиолетовый": "PURPLE", "зелёный": "GREEN", "зеленый": "GREEN",
}
# слова-уточнения Apple, которых в её словаре нет: «Space Black» → BLACK, «Natural Titanium» → NATURAL
ЛИШНЕЕ_В_ЦВЕТЕ = ("TITANIUM", "TITAN", "SPACE")


class ОшибкаЭкспорта(RuntimeError):
    """Человеческий текст, почему сделка не ушла."""


# ---------------------------------------------------------------- поля сделки

def sim_для_оценки(pas: dict) -> str:
    """Какой SIM у аппарата — словами Оценки. Пустое поле её карточка печатает как «None»."""
    if pas.get("esim_only"):
        return "E-sim"
    if pas.get("esim") or (pas.get("imei2") or "").strip():
        return "Dual sim"            # физический лоток плюс eSIM — у Apple это «две SIM»
    if pas.get("sim_в_лотке") is not None or pas.get("sim"):
        return "Стандарт"
    return "Прочее"


_НЕ_ЦВЕТ = re.compile(r"(?i)^(pro max|pro|plus|mini|air|se|max|a\d{4}|iphone)\b")


def цвет_для_оценки(цвет) -> str | None:
    """Цвет её словарём: одно английское слово заглавными.

    В карточке уже видели «Цвет: Pro A2891» — так выглядит кусок описания модели,
    принятый за цвет. А русское «чёрный / графитовый» (это мы получаем по коду корпуса)
    уехало бы в название товара МойСклада и сделало бы его нечитаемым. Не узнали цвет —
    отдаём пусто: пустое поле её карточка просто не печатает.
    """
    c = str(цвет or "").strip()
    if not c or _НЕ_ЦВЕТ.match(c) or re.fullmatch(r"(?i)a?\d{3,5}", c):
        return None
    первая = c.split("/")[0].strip().lower()          # «чёрный / графитовый» → «чёрный»
    if первая in ЦВЕТА_ОЦЕНКИ:
        return ЦВЕТА_ОЦЕНКИ[первая]
    if первая.split() and первая.split()[0] in ЦВЕТА_ОЦЕНКИ:
        return ЦВЕТА_ОЦЕНКИ[первая.split()[0]]        # «чёрный космос» → BLACK
    слова = [w for w in re.split(r"[\s_-]+", c.upper()) if w and w not in ЛИШНЕЕ_В_ЦВЕТЕ]
    if not слова or not all(w.isascii() and w.isalpha() for w in слова):
        return None                                   # не её словарь — лучше пусто, чем мусор
    return " ".join(слова)[:40]


def акб_для_оценки(здоровье, циклы=None) -> str:
    """Здоровье батареи → диапазон Оценки.

    Это не оформление: по этой строке её прайс выбирает колонку цены
    (`AKB_COL_INDEX_BY_STATE`), а приёмка — строку товара. «86%» вместо «86-90» ломает
    автооценку. Точный процент уходит отдельно, в `akb_exact`.
    """
    if здоровье is None:
        return АКБ_НЕТ
    h = int(здоровье)
    if h >= 100:
        # почти без циклов — у неё для этого отдельная кнопка и отдельная колонка в прайсе
        return АКБ_НОВАЯ if (циклы is not None and int(циклы) <= НОВАЯ_ЦИКЛОВ) else "100"
    for порог, имя in АКБ_ДИАПАЗОНЫ:
        if h >= порог:
            return имя
    return "0-74"


def статус_ремонта(вердикт_деталей: str | None) -> str | None:
    """Наш вердикт по деталям → «Ремонт статус» Оценки."""
    if вердикт_деталей == "родные":
        return СТАТУС_ЧИСТЫЙ
    if вердикт_деталей in ("замена", "ремонт"):
        return СТАТУС_РЕМОНТ
    return None                      # не подтверждено — пусть решает человек, не мы


def замки(rep: dict) -> list:
    """Блокировки, из-за которых аппарат нельзя принимать молча. Одним списком — он нужен
    и в комментарии сделки, и в карточке, которую оценщик подтверждает в Telegram."""
    найдено = []
    прав = rep.get("правовой") or {}
    sk = rep.get("sickw") or {}
    if sk.get("в_чёрном_списке") is True:
        найдено.append("ЧЁРНЫЙ СПИСОК")
    if прав.get("найти_iphone") == "включён" or sk.get("fmi_включён") is True:
        найдено.append("Найти iPhone вкл.")
    if прав.get("mdm") is True:
        найдено.append("MDM")
    return найдено


def комментарий_оценщика(rep: dict, сверка: str = "", откуда: str = "") -> str:
    """Короткая техническая сводка в поле «Комментарий оценщика»."""
    куски = []
    итог = (rep.get("детали_вердикт") or {}).get("итог")
    if итог:
        куски.append(f"Детали: {итог}")
    if сверка:
        куски.append(сверка)
    журнал = rep.get("apple_история_источник") or rep.get("apple_история_статус")
    if журнал:
        куски.append(f"Apple: {журнал}")
    если_замки = замки(rep)
    if если_замки:
        куски.append("Замки: " + ", ".join(если_замки))
    пан = rep.get("паника") or {}
    if пан.get("panic_full"):
        from ..devicelink import panic as panic_mod
        куски.append(panic_mod.словами(пан).upper())
    бат = rep.get("батарея") or {}
    if бат.get("циклы"):
        куски.append(f"Батарея: {бат.get('здоровье_%') or '?'}%, {бат['циклы']} циклов")
    if откуда:
        куски.append(откуда)
    return " · ".join(куски)[:4000]


def проверить_готовность(данные: dict) -> None:
    """Что обязано быть, чтобы сделку вообще было из чего собрать. Отдельно от отправки,
    чтобы экран оценки мог сказать сотруднику заранее, чего не хватает.

    Видео здесь не проверяем: его принимает бот, он знает, пришло ли оно, и без видео
    сделку не создаёт.
    """
    нет = []
    if not данные.get("модель"):
        нет.append("модель")
    if not данные.get("память"):
        нет.append("объём памяти")
    if not (данные.get("имя_клиента") and данные.get("телефон_клиента")):
        нет.append("имя и телефон клиента")
    if not данные.get("imei"):
        нет.append("IMEI")
    if нет:
        raise ОшибкаЭкспорта("не хватает: " + ", ".join(нет))


def посылка(данные: dict, код: str, точка: str = "") -> dict:
    """Готовая посылка для бота. Имена внутри «сделка» — колонки devices: обработчик
    кладёт их как есть, поэтому весь перевод в словарь Оценки делается здесь и проверяется
    тестами, а не на сервере.

    Магазина сделки здесь нет: его знает бот. У продавца это его закреплённая точка, а
    администратор выбирает её сам, когда сдаёт медиа. `точка` — только подпись киоска
    для карточки, в базу она не идёт."""
    проверить_готовность(данные)
    акб = данные.get("акб")
    имеи = [str(данные.get("imei") or "").strip()]
    имеи += [str(x).strip() for x in (данные.get("imei_все") or []) if str(x or "").strip()]
    return {
        "версия": ВЕРСИЯ_ПОСЫЛКИ,
        "код": str(код or ""),
        "точка": точка or "",
        "клиент": {"имя": str(данные["имя_клиента"]).strip()[:150],
                   "телефон": str(данные["телефон_клиента"]).strip()[:13]},
        "imei": list(dict.fromkeys(x for x in имеи if x)),
        "imei_проверен": bool(данные.get("imei_проверен", True)),
        "замки": list(данные.get("замки") or []),
        "сделка": {
            "model": str(данные["модель"])[:50],
            "code_name": (данные.get("код_модели") or None),
            "ddr": int(данные["память"]),
            "akb": акб_для_оценки(акб, данные.get("циклы")),
            "akb_exact": акб,
            "color": цвет_для_оценки(данные.get("цвет")),
            "sim": (данные.get("sim") if данные.get("sim") in SIM_ВАРИАНТЫ else "Прочее"),
            "box": bool(данные.get("коробка")),
            "cord": bool(данные.get("шнур")),
            "panic_full": данные.get("panic_full"),
            "phone_status": данные.get("статус_ремонта"),
            "price_grade_auto": данные.get("цена"),
            "comment": (данные.get("комментарий") or None),
            "comment_ocenka": (данные.get("комментарий_оценщика") or None),
        },
    }
